          "p1m2c4.q04.o03": "Promising every client immediate delivery overcommits you. The lesson reworks priorities before committing to anyone.",
          "p1m2c4.q04.o04": "Sticking to a stale plan ignores the new reality. The lesson reorganizes before resuming."
